$aml_li_4 = "Αποφυγή κυρώσεων";
$aml_li_5 = "Χειραγώγηση αγοράς";
$aml_li_6 = "Χρήση κλεμμένων κεφαλαίων ή παραβιασμένων λογαριασμών";
$aml_li_7 = "Οποιαδήποτε δραστηριότητα απαγορεύεται από την ισχύουσα νομοθεσία";
$aml_h2_exchange = "Συμμόρφωση ανταλλακτηρίων τρίτων";
